CREATE TABLE certificate_templates (course_id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,design JSON NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,require_assessments BOOLEAN NOT NULL DEFAULT TRUE,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(org_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE certificates (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,course_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,snapshot JSON NOT NULL,issued_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),revoked_at DATETIME(3) NULL,UNIQUE(course_id,user_id),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE ai_studio_drafts (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,author_id CHAR(36) NOT NULL,kind VARCHAR(40) NOT NULL,payload JSON NOT NULL,imported_course_id CHAR(36) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(imported_course_id) REFERENCES courses(id)) ENGINE=InnoDB;
ALTER TABLE lessons ADD COLUMN format ENUM('text','video','audio','live') NOT NULL DEFAULT 'text',ADD COLUMN duration_minutes INT NOT NULL DEFAULT 0;
CREATE TABLE lesson_notes (lesson_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,body TEXT NOT NULL,video_seconds INT NOT NULL DEFAULT 0,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(lesson_id,user_id),FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
